REPLACE INTO `homepage_sections` (`id`, `section_key`, `tag_number`, `tag_text`, `title_main`, `title_accent`, `subtitle`, `image_path`, `video_path`, `extra_text_1`, `extra_text_2`, `is_active`, `sort_order`, `updated_at`) VALUES
('1', 'sec_00_hero', '00', 'EST. 2011 · BHOPAL, MP', 'Where heritage', 'meets innovation.', 'RKDF University — Premier Private State University in Madhya Pradesh', 'images/lovable/rkdf-building-enhanced.jpg', 'images/lovable/rkdf-drone.mp4', 'APPLY NOW — ADMISSIONS 2026-27', 'EXPLORE CAMPUS', '1', '0', '2026-08-06 12:51:52'),
('2', 'sec_01_numbers', '01', 'THE INSTITUTE IN NUMBERS', 'Numbers that define us', '', 'Key milestones and stats of RKDF University', '', '', '', '', '1', '1', '2026-08-06 12:51:52'),
('3', 'sec_02_university', '02', 'THE UNIVERSITY', 'A four-decade legacy,', 'reimagined', 'RKDF University brings together eleven professional schools, thirty-five departments and a cross-disciplinary research culture.', 'images/lovable/rkdf-library.jpg', '', '\"An education worth having is one that makes you useful — to yourself, and to a world in motion.\"', '— Shri Sunil Kapoor, Chancellor', '1', '2', '2026-08-06 12:51:52'),
('4', 'sec_03_gateway', '03', 'STUDENT GATEWAY', 'Everything you need,', 'one click away.', 'Quick links to the tools, portals and resources students, parents and applicants reach for most.', '', '', '', '', '1', '3', '2026-08-06 12:51:52'),
('5', 'sec_04_schools', '04', 'SCHOOLS & FACULTIES', 'Eleven schools.', 'One purpose.', 'Explore our world-class professional schools and faculties.', '', '', 'DRAG TO EXPLORE', 'Explore school', '1', '4', '2026-08-06 12:51:52'),
('6', 'sec_05_why', '05', 'WHY RKDF', 'A university built around the', 'student.', 'Everything from our teaching philosophy to our campus design is calibrated for one outcome — graduates who leave here more prepared, more curious, and more useful.', 'images/lovable/rkdf-why-bg.jpg', '', '', '', '1', '5', '2026-08-06 12:51:52'),
('7', 'sec_06_admissions', '06', 'ADMISSIONS 2026-27', 'A simple path', 'to joining us.', 'Four transparent steps. A dedicated counsellor at every stage. Applications for the 2026-27 intake are open.', '', '', '', '', '1', '6', '2026-08-06 12:51:52'),
('8', 'sec_07_programs', '07', 'FEATURED PROGRAMS', 'Featured Programs', '', 'Explore our flagship degree programs across Engineering, Management, Pharmacy and Law.', '', '', '', '', '1', '7', '2026-08-06 12:51:52'),
('9', 'sec_08_campus', '08', 'CAMPUS LIFE', 'A campus that', 'breathes.', 'Beyond the classroom — 42 clubs, seven residential blocks, indoor and outdoor sports arenas, a two-story library, and a maker-space open around the clock.', '', '', '', '', '1', '8', '2026-08-06 12:51:52'),
('10', 'sec_09_research', '09', 'RESEARCH & INNOVATION', 'Advancing the frontiers of', 'human knowledge.', 'Fifty specialised laboratories. Nine funded research centres. A doctoral cohort working across artificial intelligence, clean energy, biosciences and public policy.', 'images/lovable/rkdf-research.jpg', '', '', '', '1', '9', '2026-08-06 12:51:52'),
('11', 'sec_10_placements', '10', 'PLACEMENTS', 'Careers that', 'go somewhere.', 'Our placement cell partners with 300+ recruiters across India and abroad, running mock interviews, CV clinics and a full-year internship track.', '', '', '', '', '1', '10', '2026-08-06 12:51:52'),
('12', 'sec_11_voices', '11', 'VOICES', 'What our graduates', 'carry with them.', 'Hear directly from our alumni who are making an impact around the globe.', '', '', '', '', '1', '11', '2026-08-06 12:51:52'),
('13', 'sec_12_news', '12', 'NEWS & EVENTS', 'This week at', 'RKDF.', 'Latest announcements, academic achievements, and campus events.', 'images/lovable/rkdf-campus-aerial.jpg', '', '', '', '1', '12', '2026-08-06 12:51:52'),
('14', 'sec_13_gallery', '13', 'CAMPUS GALLERY', 'The everyday here.', '', 'Visual glimpses of student life, state-of-the-art facilities, and campus culture.', '', '', '', '', '1', '13', '2026-08-06 12:51:52'),
('15', 'sec_14_recognition', '14', 'ACCREDITATION & RECOGNITION', 'Recognised where it counts.', '', 'Accreditations and statutory approvals from India\'s top regulatory bodies.', '', '', '', '', '1', '14', '2026-08-06 12:51:52'),
('16', 'sec_15_virtual_tour', '15', 'VIRTUAL CAMPUS EXPERIENCE', 'Take a walk through', 'campus', 'A guided cinematic tour through the quadrangle, the library, the labs and the residential blocks. Six minutes. Then decide.', 'images/lovable/rkdf-building-enhanced.jpg', 'images/lovable/rkdf-drone.mp4', 'Begin the Tour', 'Book a Campus Visit', '1', '15', '2026-08-06 12:51:52'),
('17', 'sec_16_final_cta', '16', 'ADMISSIONS 2026-27', 'Your next chapter', 'starts here.', 'Take the first step towards a transformative university experience.', '', '', 'Apply Today ↗', 'admissionform.php', '1', '16', '2026-08-06 13:01:51'),
('20', 'sec_02_leadership', '02B', 'ACADEMIC LEADERSHIP', 'Guiding vision &', 'leadership.', 'Inspiring mentorship from our Chancellor, Vice-Chancellor and Hon\'ble Governor of MP.', '', '', '', '', '1', '3', '2026-08-10 16:51:00'),
('21', 'sec_06_key_services', '06B', 'CAMPUS SERVICES & WINGS', 'Key Campus Units &', 'Portals.', 'Explore youth wings, research divisions, admissions and exam results.', '', '', '', '', '1', '7', '2026-08-10 16:51:00'),
('22', 'sec_09_shining_stars', '09B', 'ALUMNI PLACEMENT STARS', 'Placed Students —', 'Shining Stars.', 'RKDF graduates securing top corporate packages in Fortune 500 companies.', '', '', '', '', '1', '10', '2026-08-10 16:51:00'),
('23', 'sec_11_art_gallery', '11B', 'CAMPUS ART & CREATIVITY', 'Campus Life &', 'Art Gallery.', 'Glimpses of fine arts, cultural events, campus fests, and student creations.', '', '', '', '', '1', '13', '2026-08-10 16:51:00'),
('24', 'sec_14_important_links', '14B', 'STATUTORY & QUICK LINKS', 'Statutory Approvals &', 'Quick Links.', 'Direct access to official university certificates, committees, ordinances, webmail, and e-tenders.', '', '', '', '', '1', '16', '2026-08-10 16:51:00');
