('69', 'sec_11_voices', 'testimonial', 'Priya Sharma', 'M.Sc. Data Science, 2024', '', 'The research culture here doesn\'t wait for permission. I published two papers before graduation and joined a team at Amazon straight after.', 'images/lovable/rkdf-student-1.jpg', '', '', NULL, '1', '1', '2026-08-06 12:51:53', '2026-08-06 12:51:53'),
('70', 'sec_11_voices', 'testimonial', 'Arjun Verma', 'B.Tech CSE, 2023', '', 'Faculty who actually build things, labs open past midnight, and a placement cell that treated every one of my 12 offers as if it mattered.', 'images/lovable/rkdf-student-2.jpg', '', '', NULL, '2', '1', '2026-08-06 12:51:53', '2026-08-06 12:51:53'),
('71', 'sec_11_voices', 'testimonial', 'Meera Iyer', 'BA-LLB, 2024', '', 'The moot court program at RKDF is genuinely national-tier. I argued in six states before I even sat for the bar.', 'images/lovable/rkdf-student-3.jpg', '', '', NULL, '3', '1', '2026-08-06 12:51:53', '2026-08-06 12:51:53'),
