('91', 'sec_02_leadership', 'leadership', 'Dr. Sadhna Kapoor', 'Chancellor, RKDF University Bhopal', '', 'Education is a great leveler for socio-economic development of the nation. Our focus is to make quality higher education accessible and useful.', 'images/chancellor-dr-sadhna.jpg', 'Chancellor.php', 'CHANCELLOR', NULL, '1', '1', '2026-08-10 16:51:00', '2026-08-10 17:20:07'),
('92', 'sec_02_leadership', 'leadership', 'Prof. Vijay K. Agrawal', 'Vice-Chancellor, RKDF University Bhopal', '', 'Higher education in the 21st century is undergoing massive transformation. We are committed to academic excellence, innovation, and holistic student growth.', 'images/vice-chancellor-prof-vijay.jpg', 'Vice-Chancellor-Desk.php', 'VICE-CHANCELLOR', NULL, '2', '1', '2026-08-10 16:51:00', '2026-08-10 17:20:07'),
('93', 'sec_02_leadership', 'leadership', 'Shri Mangubhai Patel', 'Hon\'ble Governor of Madhya Pradesh', '', 'Greetings and best wishes to RKDF University Bhopal for empowering youth with skill-oriented higher education and nation-building values.', 'images/governor_mangubhai_patel.jpg', 'Governingbody.php', 'HON\'BLE GOVERNOR', NULL, '3', '1', '2026-08-10 16:51:00', '2026-08-10 22:38:33'),
