('97', 'sec_06_key_services', 'service', 'Why RKDF University', '40+ Years Educational Legacy', '', 'World-class campus, experienced faculty, 100+ degree programs, and 300+ placement recruiters.', 'images/lovable/rkdf-building-enhanced.jpg', 'about.php', 'ABOUT US', NULL, '4', '1', '2026-08-10 16:51:00', '2026-08-10 16:51:00'),
