('2', 'patent', 'Research Patents & Innovation', 'Research', '34 · INTELLECTUAL PROPERTY', 'Granted and published research patents by RKDF faculty & scholars.', '', 'University Patent Portfolio', 'Highlighting key patents in engineering, clean energy, and healthcare technology.', NULL, NULL, '1', '0', '2026-08-05 17:29:22'),
