('9', 'Admission_search', 'Admission Application Lookup', 'Admissions', '02 · REGISTRATION SEARCH', 'Track your submitted admission application status using Registration ID.', '', 'Application Tracker', 'Fast status lookup for submitted admission forms.', NULL, NULL, '1', '0', '2026-08-05 17:29:22'),
('10', 'vision-mission', 'Vision & Mission', 'about', '01 · INSTITUTIONAL PHILOSOPHY', 'Pioneering Higher Education, Advanced Research, and Sustainable Societal Transformation.', 'images/ai_vision/rkdf_vision_banner.jpg', 'Our Core Institutional Philosophy', 'RKDF University Bhopal is dedicated to transforming higher education by combining academic rigor, scientific innovation, and societal commitment.', '', 'Pioneering Higher Education, Advanced Research, and Sustainable Societal Transformation.', '1', '0', '2026-08-06 16:52:26'),
('11', 'about', 'About RKDF University', 'about', '01 · OVERVIEW', 'Education Glorifies the Nation — Pioneer in Skill-Based, Technology-Driven Higher Education and Advanced Research.', 'images/lovable/rkdf-why-bg.jpg', 'About RKDF University Bhopal', 'RKDF University Gandhi Nagar, Bhopal was established by Ayushmati Education and Social Society, by an act of Govt. of M.P and published in State Gazette on 19th July 2011. The University is spread over 107 acres of land near the Bhopal Airport having buildup area of 13.184 Lakh Sq.ft. and well maintained 6.31 Lakh Sq.ft. Garden in campus. The University has been approved by UGC under section 2(f) 1956 after the visit of expert committee members constituted by University Grant Commission, New Delhi.\n\nAfter the approval of Statutes & ordinances of the University by the Department of Higher Education Govt. of M.P. on 4th May 2012, the Academic Session started from the year 2012-13. All the courses run by the University have approval of concern Regulatory bodies & State Govt. also. From Academic year 2013-14, the University has introduced compulsory courses of 4 Credit on “Value Spirituality and Consciousness Development” in collaboration with Brahma Kumaris Education wing, Mount Abu, Rajasthan for all the students of undergraduate programmes which they have to pass to get a degree. The University aims to produce Youth having ethical values for the Nation.\n\nThe Strategies for imparting education to students of University is Skill based on Technology driven Education, Skill Building approach, Industry link curriculum, National outlook and more emphasis on (hands on training) practical & research orientation which have resulted in to many international awards through global competitions. The University has established, first Carbon Capture plant (CCP) in Asia and developed modified Bukhari for army for which we have been recognized at international forums.\n\nAfter valuation of students achievements at International level and achievement in the Academic and Research of the University. Hon’ble Chancellor of the University Dr. Sadhna Kapoor was awarded Honorary Professor of Oxford Academic Union, U.K. in 2017 at Switzerland and “Grand Star of Success Award” in December 2022 at Oxford University U. K. again by Oxford Academic Union U. K.\n\nExtra curriculum activities for the students, include motivational lectures of renowned personalities of India in the University regularly. In Annual Sport, eminent players of Indian team i.e. Hocky, Cricket & Badminton etc are invited as Chief Guest. Recently, for women empowerment seminar, Ms. Madhuri Dixit was present as chief guest. In cultural functions famous signers of India are also invited regularly.\n\nThe University has introduced National Education Policy (NEP-2020) for undergraduate curriculum framework from the Academic session 2022-23, with the objective to capture the imagination of the youth of our National and contemporary realties of demographic advantage globally. The University has also included 48 value added courses for our students to help them in their employment. The vision of the University is to “Produce Job Creators & Not Job Seekers”.', NULL, 'Pioneering Higher Education, Advanced Research, and Sustainable Societal Transformation at RKDF University Bhopal.', '1', '0', '2026-08-07 11:22:18'),
('12', 'objectives', 'Objectives', 'about', '02 · INSTITUTIONAL STRATEGY', 'Strategic goals driving academic quality, infrastructure growth, and student success.', 'images/ai_objectives/rkdf_objectives_banner.jpg', 'Strategic Institutional Goals', 'RKDF University Bhopal is established with the primary commitment to fulfill key strategic institutional objectives across education, research, and societal development.', NULL, 'Strategic goals driving academic quality, infrastructure growth, and student success.', '1', '0', '2026-08-06 16:52:26'),
('13', 'idp', 'Institutional Development Plan (IDP)', 'about', '03 · INSTITUTIONAL DEVELOPMENT', '10-Year Strategic Roadmap for Academic Expansion, Research Excellence, and World-Class Infrastructure.', 'images/lovable/rkdf-building-enhanced.jpg', 'RKDF University Institutional Development Plan (2022-2032)', 'The Institutional Development Plan (IDP 2022-2032) of RKDF University Bhopal outlines a transformative 10-year strategic roadmap aligned with the National Education Policy (NEP-2020) and Sustainable Development Goals (SDGs).\n\nKey Strategic Pillars:\n1. Academic Expansion & Curriculum Modernization: Integration of Choice-Based Credit Systems (CBCS), multidisciplinary skill certifications, and digital blended learning.\n2. Research Incubation & Patent Acceleration: Setting up state-of-the-art research centers, expanding Carbon Capture Plant innovations, and increasing Scopus/WoS indexed research output.\n3. Industry 4.0 Collaboration & Global Alliances: MoUs with leading multinational companies, international credit transfer programs, and entrepreneurship seed funding.\n4. Green Campus & Infrastructure Scaling: Expanding solar power grids, eco-friendly green gardens, digital central library, and modern sports complexes.', NULL, 'Long-term strategic growth roadmap, academic expansion, and infrastructure enhancement plan.', '1', '0', '2026-08-07 11:25:37'),
('18', 'org-structure', 'Organizational Structure', 'about', '04 · GOVERNANCE & HIERARCHY', 'Statutory Administrative Organogram, Executive Leadership, and Academic Senate Governance.', 'images/lovable/rkdf-students-quad.jpg', 'University Administrative Hierarchy & Organogram', 'RKDF University Bhopal is governed by statutory authorities established under MP Legislature Act. The University administrative hierarchy ensures seamless operational leadership, academic excellence, and student-centric administration.\n\nGovernance & Administrative Hierarchy:\n• Chancellor & Sponsoring Society: Apex visionary authority providing overall direction and strategic guidance.\n• Pro-Chancellor & Vice-Chancellor: Executive heads driving academic delivery, research innovation, and quality assurance.\n• Governing Body & Board of Management: Supreme statutory councils approving policies, budgets, and appointments.\n• Academic Council & Boards of Studies: Academic senate formulating curricula, examination schemes, and research regulations.\n• Registrar & Administrative Officers: Chief executive officers overseeing day-to-day campus administration, admissions, and regulatory compliance.', 'rkdf, university, bhopal, organizational structure', 'Administrative hierarchy, academic senate, executive leadership, and board structures.', '1', '5', '2026-08-07 11:25:37'),
('19', 'chancellor', 'Chancellor\'s Desk 2026', 'about', '03 · EXECUTIVE LEADERSHIP', 'A message of vision, institutional mission, and educational empowerment from Dr. Sadhna Kapoor, Chancellor.', 'images/ai_chancellor/rkdf_chancellor_banner.jpg', 'Message From The Chancellor', 'Education is the prerequisite for socio-economic development of the Nation in general and people in particular. Not enough educational facilities are available for professional studies in Engineering, Health sciences, Management, and Computer Science.\r\n\r\nRKDF Education Group realized these limitations and established technical education institutions in Madhya Pradesh starting in 1995, growing to more than 100 colleges across Bhopal, Sehore, Indore, and Rewa.\r\n\r\nThe RKDF Group established RKDF University at Gandhi Nagar, Bhopal under MP Legislature Act, providing undergraduate, postgraduate, M.Phil, and Ph.D degrees.\r\n\r\nAs Chancellor, it is my endeavour to provide modern educational facilities, research guidance, and living comforts to empower young minds to serve the Nation with dedication.\r\n\r\nUpdated via Admin CMS.', 'rkdf, university, bhopal, chancellor\'s desk', 'A message of vision, institutional mission, and educational empowerment from Dr. Sadhna Kapoor, Chancellor.', '1', '6', '2026-08-06 16:53:51'),
('20', 'pro-chancellor', 'Pro-Chancellor Desk', 'about', '04 · EXECUTIVE LEADERSHIP', 'Guiding strategic initiatives, academic quality assurance, research, and international university linkages.', 'images/lovable/rkdf-why-bg.jpg', 'Message From Pro-Chancellor', 'Education is for transition of a competent scholar to a seasoned professional equipped with expertise in the chosen field. The standard requirements are increasing with every passing year, what has been extra ordinary in the last decade is merely termed sufficient. The levels of desired excellence are increasing in this competitive era, the scholar needs to uplift their levels of knowledge and inculcate a diverse range of acquaintance to attain decisive excellence in the desired fields. In this knowledge driven era, the plethora of knowledge, student centric methods, advanced teaching methodologies have synergized learning and ensured students attract a good quantum of knowledge and expertise. The value added course, special classes and workshops and expert lectures have further positive impact on enhancing students learning and abilities.\n\nRKDF University, Bhopal among the top educational hubs of central India has been catering the needs by empowering its students with diverse set of knowledge, expertise, through several of its duly approved programs offered under various faculties, with state of-the-art facilities, infrastructure and well qualified faculty and developing a sound professional resource for the nation. There are numerous functional MOU’s with National and International academic institutions and industries that opens new opportunities in skill and competence progression.\n\nExemplary success attained by students under guidance of learned faculties, while working on most advanced techniques and facility; generating intellectual property rights for themselves and University are source of energy and inspiration.\n\nThe faculties and scholars of University are involved in cutting edge research which are highlighted and appreciated at national and international platforms. The University has also extended its Carbon Capture and Sequestration plant to scientists of CSIR labs who are exploring possibilities and innovations feasible for environment mitigation and societal use.\n\nThe emphasis on inclusive development of scholars has led learning as a fun filled activity at RKDF University, Bhopal and hence is a first choice destination of students.\n\nWe welcome you to be part of the development and success of professionals.\n\nWishing the scholars - Happy Learning', 'rkdf, university, bhopal, pro-chancellor desk, dr siddharth kapoor', 'Pro-Chancellor Desk - RKDF University Bhopal. Read the message from Dr. Siddharth Kapoor, Pro-Chancellor.', '1', '7', '2026-08-14 10:30:24'),
('21', 'vc-desk', 'Vice Chancellor\'s Deskkkkkk', 'about', '05 · EXECUTIVE LEADERSHIP', 'Academic vision, research innovation, and quality assurance from Vice-Chancellor Office.', 'images/ai_vice_chancellor/rkdf_vc_banner.jpg', 'Message From The Vice-Chancellor', 'Higher education in the country is at the threshold of major institutional reforms targeted towards cutting edge R&D and innovations. The major challenges before the upcoming and emerging Universities apart from quality of teaching and learning process are the need of experienced and enlightened faculty. Network of knowledge management, creative teaching and research, strong industry interface and innovative curriculum are the need of the day. Apart from this the Nation is moving forward by implementing NEP2020.\r\n\r\nRKDF University is marching towards meeting these challenges to become a \'Global Knowledge Enterprise\'. The University has a seamless synergy between Humanities, Social Sciences, Science and Engineering and we are targeting towards breaking molds of traditional departmental boundaries through interdisciplinary approach in teaching and research. We are also striving for creating knowledge network and connections with the national and global professional bodies, international centers of higher learning, industries for skill development and also with the society for sharing fruits of knowledge with the masses.\r\n\r\nWe, the RKDF Faculty Members and the Staff along with Our Learned Management are committed to build this University a real knowledge hub and, to work towards shaping the top class career of our students. We are moving ahead to help the villages through our extension programs. For this our resources have been mobilized for strengthening the youth & woman of the nearby village.\r\n\r\nWe do welcome your suggestions and feedback if we can work together for further improvement, in turn, enabling us to continue imparting world class education.\r\n\r\nWith Best Wishes for Ever to Our Students!', 'rkdf, university, bhopal, vice chancellor\'s desk', 'Academic vision, research innovation, and quality assurance from Vice-Chancellor Office.', '1', '8', '2026-08-20 15:24:11'),
('22', 'dgm', 'Director General Management (DGM) Profile', 'about', '06 · EXECUTIVE ADMINISTRATION', 'Overseeing operational management, strategic planning, and campus administrative workflows under Dr. B. N. Singh.', 'images/lovable/rkdf-library.jpg', 'Director General Management (DGM) Office', 'The Director General Management (DGM) Office at RKDF University, Bhopal is responsible for overseeing operational management, strategic planning, infrastructure development, and day-to-day administrative execution across all university faculties and constituent units.\n\nUnder the guidance of Dr. B. N. Singh, Director General Management, the DGM Office ensures seamless academic administration, robust student support services, campus facility optimization, and institutional quality management.\n\nKey Responsibilities & Focus Areas:\n• Operational Leadership & Administrative Coordination across University Departments\n• Infrastructure Expansion, Maintenance, and Resource Management\n• Student Welfare, Discipline, and Enhancement of Campus Amenities\n• Strategic Planning, Policy Implementation, and Quality Assurance\n• Fostering Industry Linkages, Inter-Departmental Synergies, and Institutional Growth\n\nEmail Contact: drbnsingh@rkdf.ac.in', 'rkdf, university, bhopal, director general management, dgm profile, dr b n singh', 'Director General Management (DGM) Profile - RKDF University Bhopal. Learn about Dr. B. N. Singh and the DGM Office.', '1', '9', '2026-08-14 10:32:38'),
('23', 'dgr', 'Director General Research (DGR) Profile', 'about', '10 · RESEARCH LEADERSHIP', 'Spearheading R&D grants, patent filing, doctoral research oversight, and international publications under Dr. Vinod Kumar Sethi.', 'images/lovable/rkdf-research.jpg', 'Director General Research (DGR) Office', 'The Director General Research (DGR) Office at RKDF University, Bhopal plays a pivotal role in driving academic research excellence, innovation, sponsored R&D projects, and international academic linkages across all university departments.\n\nUnder the distinguished leadership of Dr. Vinod Kumar Sethi, Director General Research, the DGR Office promotes cutting-edge research, patent creation, scientific publications, and collaborative projects with premier national and international institutions (including CSIR, DST, AICTE, and ISRO).\n\nKey Responsibilities & Research Focus:\n• Promoting Cutting-edge R&D and Multidisciplinary Innovation Initiatives\n• Facilitating Patent Filing, Intellectual Property Rights (IPR), and Technology Commercialization\n• Overseeing Doctoral Research (Ph.D) & Post-Doctoral Fellowships\n• Coordination of National & International Conferences, Seminars, and Workshops\n• Industry-Academia MoUs, Carbon Capture & Sequestration Research, and Environmental Innovation\n\nEmail Contact: vksethi1949@gmail.com', 'rkdf, university, bhopal, director general research, dgr profile, dr vinod kumar sethi', 'Director General Research (DGR) Profile - RKDF University Bhopal. Learn about Dr. Vinod Kumar Sethi and the DGR Office.', '1', '10', '2026-08-14 10:34:17'),
('24', 'registrar', 'Registrar Profile', 'about', '11 · EXECUTIVE ADMINISTRATION', 'Custodian of university records, legal compliance, statutory reporting, admissions, and academic secretariat under Dr. Satendra S. Thakur.', 'images/lovable/rkdf-building-enhanced.jpg', 'Office of the Registrar', 'The Office of the Registrar at RKDF University, Bhopal serves as the chief administrative office responsible for maintaining statutory compliance, university records, student admissions, enrollment verifications, academic secretariat, and official university communications.\n\nUnder the leadership of Dr. Satendra S. Thakur (MBA, Ph.D.), Registrar, the Office ensures smooth coordination with statutory councils (UGC, AICTE, PCI, BCI, INC, COA, CCH, CCIM, and MPPURC), legal governance, board meetings, and academic policy implementation.\n\nKey Responsibilities & Secretariat Functions:\n• Custodian of University Records, Seal, and Statutory Documentation\n• Academic Secretariat for Governing Body, Board of Management, and Academic Council Meetings\n• Coordination with Statutory Bodies & Regulatory Councils (UGC, MPPURC, AICTE, PCI, BCI, COA)\n• Enrollment Verification, Student Registrations, Degree Certificates, and Transcripts\n• Legal Compliance, Official University Notifications, and Inter-Departmental Coordination\n\nContact Information:\nLandline: +91 755-2740395\nEmail Contact: registrar@rkdf.ac.in', 'rkdf, university, bhopal, registrar profile, dr satendra s thakur', 'Registrar Profile - RKDF University Bhopal. Learn about Dr. Satendra S. Thakur and the Registrar Office.', '1', '11', '2026-08-14 10:37:07'),
('25', 'other-officers', 'Other Officer\'s Directory', 'about', '12 · EXECUTIVE ADMINISTRATION', 'Key administrative officers, exam controller, dean student welfare, and chief finance officer of RKDF University Bhopal.', 'images/lovable/rkdf-library.jpg', 'Executive & Administrative Officers', 'The Executive & Administrative Officers of RKDF University, Bhopal manage key operational, academic, financial, and student support departments across the campus.\n\nWorking in synergy with the Chancellor, Vice-Chancellor, Pro-Chancellor, and Registrar offices, our executive officers ensure seamless academic administration, rigorous examination standards, financial integrity, and comprehensive student welfare services.', 'rkdf, university, bhopal, other officers directory, exam controller, dsw, cfao', 'Other Officer\'s Directory - RKDF University Bhopal. Contact profiles of Exam Controller, Dean Student Welfare, and Chief Finance Officer.', '1', '12', '2026-08-14 10:38:37'),
('26', 'dean', 'Faculty Deans Directory', 'about', '13 · ACADEMIC LEADERSHIP', 'Directory of Deans leading constituent faculties of Engineering, Pharmacy, Management, Science, Law, Agriculture, and Paramedical across RKDF University Bhopal.', 'images/lovable/rkdf-students-quad.jpg', 'Deans of University Faculties', 'The Deans of Faculties at RKDF University, Bhopal provide academic vision, curriculum governance, research supervision, and departmental leadership across all university faculties.\n\nWorking in close coordination with Institute Heads and Department Heads (HODs), our Faculty Deans ensure state-of-the-art education, multidisciplinary research, accreditation standards, and student excellence.', 'rkdf, university, bhopal, faculty deans directory, deans list', 'Faculty Deans Directory - RKDF University Bhopal. Meet the academic Deans heading university faculties.', '1', '13', '2026-08-14 10:40:30'),
('27', 'hod', 'Institute Head / HOD\'s', 'about', '11 · DEPARTMENTAL LEADERSHIP', 'Directory of Heads of Departments (HODs) across all academic disciplines.', 'images/lovable/rkdf-engineering.jpg', 'Heads of Departments (HODs)', 'Leading departmental academic delivery, laboratories, and student mentoring.', 'rkdf, university, bhopal, institute head / hod\'s directory', 'Directory of Heads of Departments (HODs) across all academic disciplines.', '1', '14', '2026-08-06 15:15:06'),
('28', 'governing-body', 'Governing Body', 'about', '12 · APEX GOVERNANCE', 'Apex statutory governing body of RKDF University Bhopal under MP Act.', 'images/ai_governing/rkdf_governing_banner.jpg', 'Apex Governing Council', 'The Governing Body is the apex statutory authority of RKDF University Bhopal established under Section 22 of the Madhya Pradesh Niji Vishwavidyalaya (Sthapana Avam Sanchalan) Adhiniyam, 2007.\n\nIt formulates institutional policies, approves budget allocations, and guides long-term strategic expansion.', 'rkdf, university, bhopal, governing body', 'Apex statutory governing body of RKDF University Bhopal under MP Act.', '1', '15', '2026-08-06 16:52:26'),
('29', 'bom', 'Board of Management (BoM)', 'about', '16 · STATUTORY GOVERNANCE', 'Official Board of Management constituted under Statute 10 (Order No. 1694 /RKDF/2022) of RKDF University Bhopal.', 'images/lovable/rkdf-library.jpg', 'Constitution of Board of Management', 'As per Provision in RKDF University, Bhopal Statute 10 regarding Constitution of Board of Management & after getting nomination from Sponsoring Society of Ayushmati Education & Social Society and obtaining nomination under Statute 10 (sub-clause IV & V) by competent authority, the Board of Management of RKDF University Bhopal is constituted under Order No. 1694 /RKDF/2022.\n\nThe Board of Management is the principal executive organ responsible for administrative governance, academic appointments, financial oversight, and infrastructure development of the University.', 'rkdf, university, bhopal, board of management, bom members, statute 10', 'Board of Management (BoM) - RKDF University Bhopal. Official list of constituted members under Statute 10.', '1', '16', '2026-08-14 10:46:09'),
('30', 'academic-council', 'Academic Council', 'about', '17 · ACADEMIC GOVERNANCE', 'Official Academic Council constituted under Statute 11 (Order No. 641/RKDF/2024) of RKDF University Bhopal.', 'images/lovable/rkdf-students-quad.jpg', 'Constitution of Academic Council', 'As per Provision of RKDF University Bhopal Statute 11 and after approval of Competent Authority, the Academic Council of the University is constituted under Office Order No. 641/RKDF/2024 dated 09/03/2024.\n\nThe Academic Council is the principal academic body of RKDF University Bhopal. It maintains and regulates standards of instruction, education, research, curricula, degree awards, and examination systems across all university faculties.', 'rkdf, university, bhopal, academic council, statute 11, members list 2024', 'Academic Council - RKDF University Bhopal. Official list of constituted members under Statute 11.', '1', '17', '2026-08-14 10:48:53'),
('31', 'bos', 'Board of Studies (BOS)', 'about', '18 · CURRICULUM & SYLLABUS BOARD', 'Departmental Boards of Studies designing innovative CBCS and NEP-2020 course curricula across all university faculties.', 'images/lovable/rkdf-research.jpg', 'Departmental Boards of Studies (BOS) Secretariat', 'The Board of Studies (BOS) is the statutory academic authority responsible for designing, revising, and modernizing course curricula, syllabi, schemes of examination, and textbook references across all constituent faculties at RKDF University Bhopal.\n\nWorking under the guidance of the Academic Council, the Board of Studies meets annually to align university degree programs with the National Education Policy (NEP-2020), Choice Based Credit System (CBCS), outcome-based education (OBE), and current industry requirements.', 'rkdf, university, bhopal, board of studies, bos, curriculum, syllabus, nep-2020', 'Board of Studies (BOS) - RKDF University Bhopal. Faculty Board of Studies constitutions and syllabus regulations.', '1', '18', '2026-08-14 10:50:44'),
('32', 'national-advisory', 'Statutory & National Core Advisory Bodies', 'about', '19 · ADVISORY & GOVERNANCE', 'Eminent national academicians, scientists, and industry leaders guiding RKDF University Bhopal.', 'images/lovable/rkdf-why-bg.jpg', 'National Core Advisory Group', 'The National Core Advisory Group and Statutory Advisory Bodies of RKDF University Bhopal comprise eminent academicians, scientists, former Vice-Chancellors, UGC/ICAR/IAUA experts, and senior industry leaders.\n\nThe Advisory Council provides strategic direction, research governance, national ranking frameworks (NIRF), accreditation standards (NAAC), and academic innovation across all university faculties.', 'rkdf, university, bhopal, statutory bodies, national core advisory group, advisory board', 'Statutory & National Core Advisory Bodies - RKDF University Bhopal. National experts guiding university growth and research.', '1', '19', '2026-08-14 10:57:43'),
('33', 'local-advisory', 'Local Core Advisory Group', 'about', '20 · LOCAL ADVISORY & EXECUTION', 'Executive advisory body comprising college Directors, Principals, and Emeritus Faculty executing national recommendations across RKDF University.', 'images/lovable/rkdf-building-enhanced.jpg', 'Local Core Advisory Group (LCAG)', 'A Local Core Group comprised of selected Directors, Principals, and Emeritus Faculty from RKDF University constituent colleges has been formed to pursue and execute the strategic recommendations of the National Core Advisory Group.\n\nLearning at RKDF University must be consummate — transcending traditional classroom boundaries to create an immersive academic environment where education seamlessly integrates with experiential learning, industry interaction, and all-round student development.', 'rkdf, university, bhopal, local core advisory group, local advisory committee', 'Local Core Advisory Group - RKDF University Bhopal. Directors, Principals & Emeritus Faculty implementing academic excellence.', '1', '20', '2026-08-14 10:59:43'),
('34', 'public-disclosure', 'Public Self Disclosure', 'about', '18 · MANDATORY STATUTORY DISCLOSURE', 'Mandatory Statutory Self-Disclosure under UGC & MP Private University Regulatory Commission (MPPURC).', 'images/lovable/rkdf-why-bg.jpg', 'Mandatory University Public Self-Disclosure', 'In compliance with the directives of the University Grants Commission (UGC) and Madhya Pradesh Private University Regulatory Commission (MPPURC), RKDF University Bhopal maintains complete transparency regarding statutory approvals, campus infrastructure, academic faculties, fee schedules, and student intake capacities.\n\nDisclosed Statutory Parameters:\n1. University Establishment & Gazette Notification: MP Act No. 17 of 2011 dated 19th July 2011.\n2. UGC Recognition: Approved under Section 2(f) of UGC Act 1956.\n3. Statutory Council Approvals: AICTE, PCI, BCI, COA, NCTE, INC, NCH, and NCISM.\n4. Land & Campus Builtup Area: 107 Acres campus land with 13.184 Lakh Sq.ft. builtup area.\n5. Fee Structure & Ordinances: Approved by MPPURC and Department of Higher Education Govt of MP.', 'rkdf, university, bhopal, public self disclosure', 'Mandatory public disclosure document as per UGC and MP Regulatory Commission.', '1', '21', '2026-08-07 11:25:37'),
('35', 'imggallery', 'Photo Gallery', 'about', '19 · CAMPUS MEDIA', 'Vibrant photo gallery capturing campus events, convocations, cultural fests, and sports.', 'images/lovable/rkdf-students-quad.jpg', 'RKDF Campus Life Gallery', 'Visual glimpses of academic ceremonies, student activities, and modern facilities.', 'rkdf, university, bhopal, photo gallery', 'Vibrant photo gallery capturing campus events, convocations, cultural fests, and sports.', '1', '22', '2026-08-06 15:15:06'),
('40', 'management', 'Management', 'academic', 'ACADEMIC · MANAGEMENT', 'Faculty of Management Studies offering MBA & BBA degree programs.', 'images/lovable/rkdf-students-quad.jpg', 'Faculty of Management Studies', 'The Faculty of Management Studies at RKDF University Bhopal offers industry-aligned MBA, BBA, and Executive Management degrees.\n\nOur curriculum integrates case studies, corporate internships, live stock market simulations, and guest lectures by Fortune 500 executives.', '', 'Faculty of Management Studies offering MBA & BBA degree programs.', '1', '0', '2026-08-06 16:52:26'),
('41', 'commerce', 'Commerce', 'academic', 'ACADEMIC · COMMERCE', 'Faculty of Commerce offering B.Com (Hons), M.Com & Corporate Finance.', 'images/lovable/rkdf-students-quad.jpg', 'Faculty of Commerce', 'Financial literacy, corporate accounting, and taxation studies.', NULL, 'Faculty of Commerce offering B.Com (Hons), M.Com & Corporate Finance.', '1', '0', '2026-08-06 15:15:06'),
('43', 'science', 'Science', 'academic', 'ACADEMIC · SCIENCE', 'Faculty of Science offering B.Sc (Hons), M.Sc in Biotech, Chem, Physics & Math.', 'images/lovable/rkdf-research.jpg', 'Faculty of Science', 'Advanced scientific research and laboratory education.', 'rkdf, university, bhopal, faculty of science', 'Faculty of Science offering B.Sc (Hons), M.Sc in Biotech, Chem, Physics & Math.', '1', '2', '2026-08-06 15:15:06'),
('45', 'engineering', 'Engineering & Technology', 'academic', 'ACADEMIC · ENGINEERING', 'Faculty of Engineering & Technology offering B.Tech & M.Tech degrees.', 'images/lovable/rkdf-engineering.jpg', 'Faculty of Engineering & Technology', 'The Faculty of Engineering & Technology comprises AICTE approved engineering institutes equipped with modern computer networks, robotics labs, CAD/CAM centers, and AI research stations.\n\nWe offer B.Tech & M.Tech programs in Computer Science, Artificial Intelligence, Civil, Mechanical, and Electrical Engineering.', 'rkdf, university, bhopal, faculty of engineering & technology', 'Faculty of Engineering & Technology offering B.Tech & M.Tech degrees.', '1', '4', '2026-08-06 16:52:26'),
('46', 'pharmacy', 'Pharmacy', 'academic', 'ACADEMIC · PHARMACY', 'Faculty of Pharmaceutical Sciences offering PCI approved B.Pharm & M.Pharm.', 'images/lovable/rkdf-research.jpg', 'Faculty of Pharmaceutical Sciences', 'The Faculty of Pharmaceutical Sciences is approved by the Pharmacy Council of India (PCI). We offer B.Pharm, M.Pharm, and Pharm.D degrees supported by advanced HPLC labs, sterile compounding units, and medicinal plant garden.', 'rkdf, university, bhopal, faculty of pharmaceutical sciences', 'Faculty of Pharmaceutical Sciences offering PCI approved B.Pharm & M.Pharm.', '1', '5', '2026-08-06 16:52:26'),
('47', 'law', 'Law', 'academic', 'ACADEMIC · LAW', 'BCI approved B.A. LL.B (Hons), LL.B, and LL.M legal degree programs.', 'images/lovable/rkdf-building-enhanced.jpg', 'Faculty of Law', 'Moot court hall, legal aid clinic, and judicial service preparation.', 'rkdf, university, bhopal, faculty of law', 'BCI approved B.A. LL.B (Hons), LL.B, and LL.M legal degree programs.', '1', '6', '2026-08-06 15:12:20'),
('48', 'agriculture', 'Agriculture', 'academic', 'ACADEMIC · AGRICULTURE', 'B.Sc (Hons) Agriculture degree with 50+ acres of experimental research farm.', 'images/lovable/rkdf-why-bg.jpg', 'Faculty of Agriculture', 'Sustainable farming, agronomy, soil testing, and agricultural economics.', 'rkdf, university, bhopal, faculty of agriculture', 'B.Sc (Hons) Agriculture degree with 50+ acres of experimental research farm.', '1', '7', '2026-08-06 15:15:06'),
('49', 'architect', 'Architecture', 'academic', 'ACADEMIC · ARCHITECTURE', 'Council of Architecture (COA) approved B.Arch degree building urban designers.', 'images/lovable/rkdf-building-enhanced.jpg', 'Faculty of Architecture & Planning', 'Architectural design studios, 3D printing, and sustainable urban planning.', 'rkdf, university, bhopal, faculty of architecture & planning', 'Council of Architecture (COA) approved B.Arch degree building urban designers.', '1', '8', '2026-08-06 15:15:06'),
('50', 'fee-structure', 'University Approved Tuition & Hostel Fee Structure 2026-27', 'admissions', 'ADMISSIONS · FEE STRUCTURE 2026-27', 'Approved annual tuition fee structure, hostel fees, bus transport charges, and exam fees.', 'images/lovable/rkdf-students-quad.jpg', 'Fee Structure & Financial Guidelines 2026-27', 'Tuition fees at RKDF University Bhopal are fixed in accordance with MP Private University Regulatory Commission directives.\n\nDetailed course-wise fee structures and installment schedules are available in the official document below.', 'rkdf, university, bhopal, university fees structure 2026-27', 'Transparent course-wise fee schedule across all faculties.', '1', '9', '2026-08-14 12:03:42'),
('51', 'exam-notice', 'Examination Notices & Datesheets', 'examination', 'EXAMINATION · NOTICES & CIRCULARS', 'Controller of Examinations notifications, semester datesheets, exam fee circulars, and revaluation forms.', 'images/lovable/rkdf-building-enhanced.jpg', 'Examination Branch Secretariat Notifications', 'Welcome to the Controller of Examinations Secretariat at RKDF University Bhopal. Official examination circulars, semester datesheets, admit card notifications, revaluation forms, and fee payment deadlines for all undergraduate, postgraduate, diploma, and doctoral courses are published below.\n\nStudents can view and download official signed PDF notifications and datesheets directly.', 'rkdf, university, bhopal, examination notice, exam timetable, datesheet, revaluation form', 'Examination Notices & Datesheets - RKDF University Bhopal. Download official exam notifications and datesheets.', '1', '10', '2026-08-14 11:14:04'),
('52', 'result', 'Examination Results', 'examination', '73 · ONLINE RESULTS & REVALUATION PORTAL', 'Declared semester examination results, ERP student marksheet login, revaluation application deadlines, and official grade circulars.', 'images/lovable/rkdf-building-enhanced.jpg', 'Declared Examination Results & Scorecards', 'Welcome to the Controller of Examinations Online Results Portal at RKDF University Bhopal. Below are declared semester examination results for undergraduate, postgraduate, diploma, nursing, pharmacy, BAMS, and BHMS programs.\n\nStudents can click on ERP Login to access detailed digital scorecards using their Enrollment Number.', 'rkdf, university, bhopal, examination results, erp result login, revaluation form', 'Examination Results - RKDF University Bhopal. Check semester examination results online.', '1', '11', '2026-08-14 11:26:12'),
('53', 'rnd-projects', 'R&D Sponsored Research Projects & Innovation', 'rnd', 'RESEARCH & DEVELOPMENT · SPONSORED PROJECTS', 'Government funded research projects (DST, AICTE, ISRO, CSIR), innovation labs, patents, and technology transfer initiatives.', 'images/lovable/rkdf-research.jpg', 'Ongoing & Completed Research Projects', 'The Research & Development (R&D) Cell at RKDF University Bhopal leads groundbreaking interdisciplinary research sponsored by premier national funding agencies including DST (Department of Science & Technology), AICTE, ISRO, CSIR, and ICAR.\n\nOur research ecosystem spans advanced carbon capture technology plants, solar energy systems, pharmaceutical formulations, agricultural biotechnology, and AI-driven engineering innovations.', 'rkdf, university, bhopal, rnd projects, research grants, dst funded projects', 'R&D Sponsored Research Projects - RKDF University Bhopal. Download research project lists and overview reports.', '1', '12', '2026-08-14 11:48:24'),
('54', 'patents', 'University Patents', 'rnd', 'R&D · PATENTS', 'Published and granted national/international patents filed by university scholars.', 'images/lovable/rkdf-research.jpg', 'Patents & Intellectual Property Cell', 'List of granted and published patents.', 'rkdf, university, bhopal, university patents & intellectual property', 'Published and granted national/international patents filed by university scholars.', '1', '13', '2026-08-06 15:15:06'),
('55', 'phd-admission', 'Ph.D Admission Guidelines & Entrance Test', 'rnd', 'DOCTORAL STUDIES · ADMISSION PORTAL', 'Official guidelines, eligibility criteria, entrance test dates, and online application for Ph.D programs.', 'images/lovable/rkdf-research.jpg', 'Ph.D Admission & Entrance Test Secretariat', 'Admissions to Ph.D programs at RKDF University are conducted in accordance with UGC (Minimum Standards and Procedure for Award of Ph.D. Degree) Regulations.\n\nSelection is based on the All India Ph.D Entrance Examination followed by a Doctoral Interview & Synopsis Presentation.', 'rkdf, university, bhopal, doctor of philosophy (ph.d) admissions', 'Entrance exam rules, RDC guidelines, and doctoral application procedure.', '1', '14', '2026-08-14 11:56:05'),
('56', 'admission-apply', 'Online Admission Application', 'admissions', 'ADMISSIONS · APPLY ONLINE', 'Direct online admission portal for session 2026-27 across all constituent colleges and degree courses.', 'images/lovable/rkdf-students-quad.jpg', 'Online Application Form 2026-27', 'Fill out your basic details, choose your degree program, upload documents, and receive instant application registration ID.', 'rkdf, university, bhopal, online admission application form 2026-27', 'Direct online admission portal for session 2026-27 across all constituent colleges and degree courses.', '1', '15', '2026-08-06 15:12:20'),
('58', 'prospectus', 'University Prospectus', 'admissions', 'ADMISSIONS · PROSPECTUS', 'Comprehensive information brochure covering campus infrastructure, academic faculties, hostels, sports, and placement highlights.', 'images/lovable/rkdf-building-enhanced.jpg', 'Official Information Brochure Session 2026-27', 'Explore the complete academic landscape, faculty profiles, research facilities, and campus life at RKDF University Bhopal.', 'rkdf, university, bhopal, download official prospectus 2026-27', 'Comprehensive information brochure covering campus infrastructure, academic faculties, hostels, sports, and placement highlights.', '1', '17', '2026-08-06 15:12:20'),
('59', 'syllabus', 'Syllabus', 'academic', 'ACADEMIC · SYLLABUS', 'Official CBCS course scheme and syllabus for all UG & PG programs.', 'images/lovable/rkdf-students-quad.jpg', 'Course Curricula & Examination Scheme', 'Download official syllabus PDFs for Engineering, Management, Pharmacy & Science.', NULL, 'Official CBCS course scheme and syllabus for all UG & PG programs.', '1', '0', '2026-08-06 15:15:06'),
('60', 'admission-notice', 'Admission Notice, Courses & Important Dates 2026-27', 'admissions', 'ADMISSIONS · OFFICIAL NOTICES', 'Official notification regarding course eligibility, application schedules, entrance exam dates, and last date for submission of forms.', 'images/lovable/rkdf-students-quad.jpg', 'Admission Notification & Important Dates 2026-27', 'Applications are invited for Undergraduate, Postgraduate, Diploma, and Ph.D programs for Academic Session 2026-27 across all constituent colleges of RKDF University Bhopal.\n\nCandidates can apply online through the official admission portal or visit the campus admission cell.', '', 'Official notification regarding course eligibility, application schedules, entrance exam dates, and last date for submission of forms.', '1', '0', '2026-08-14 11:59:25'),
('61', 'international', 'International', 'general', '', NULL, '', '', NULL, NULL, NULL, '1', '0', '2026-08-06 15:07:05');
REPLACE INTO `site_pages` (`id`, `page_slug`, `page_title`, `category`, `eyebrow`, `hero_subtitle`, `hero_bg_image`, `intro_heading`, `intro_text`, `meta_keywords`, `meta_description`, `is_active`, `sort_order`, `updated_at`) VALUES
('62', 'phd-subjects', 'Ph.D Subjects Offered & Research Specializations', 'rnd', 'DOCTORAL STUDIES · SUBJECTS OFFERED', 'Comprehensive list of academic disciplines and research specializations offered for Ph.D admission.', 'images/lovable/rkdf-research.jpg', 'Ph.D Academic Specializations Directory', 'RKDF University offers Doctoral (Ph.D) research programs across Engineering, Pharmacy, Management, Science, Agriculture, Law, Humanities, and Commerce.\n\nCandidates can review the approved research subjects and intake capacity below.', NULL, 'List of Ph.D subject streams, seats available & eligibility.', '1', '0', '2026-08-14 11:56:05'),
('64', 'admission-rules', 'Admission Rules, Regulations & Eligibility 2026-27', 'admissions', 'ADMISSIONS · RULES & ORDINANCES', 'Statutory admission ordinances, reservation criteria, domicile regulations, and document verification guidelines.', 'images/lovable/rkdf-students-quad.jpg', 'Regulatory Admission Ordinances & Rules', 'Admissions at RKDF University Bhopal are governed by MP Private University Regulatory Commission norms, UGC guidelines, and statutory councils including AICTE, PCI, BCI, COA, and INC.\n\nSelection is merit-based through qualifying examinations and national/state entrance tests.', 'rkdf, university, bhopal, admission rules 2026-27', 'Statutory admission ordinances, reservation criteria, domicile regulations, and document verification guidelines.', '1', '2', '2026-08-14 11:59:25'),
('65', 'cuet-mapping', 'CUET (UG) Course Mapping & Eligibility Matrix 2026', 'admissions', 'ADMISSIONS · CUET UG 2026 MAPPING', 'Common University Entrance Test (CUET UG) course mapping, domain subject combinations, and merit eligibility.', 'images/lovable/rkdf-students-quad.jpg', 'CUET (UG) Subject Combination Mapping Matrix', 'Candidates appearing for CUET UG conducted by NTA can map their domain subjects for direct merit admission into RKDF University undergraduate degree programs.\n\nReview the course-wise domain paper requirements below.', 'rkdf, university, bhopal, mapping list for cuet(ug)', 'Common University Entrance Test (CUET UG) course mapping, domain subject combinations, and merit eligibility.', '1', '3', '2026-08-14 11:59:25'),
('67', 'international-admissions', 'International & NRI Admissions Secretariat', 'admissions', 'ADMISSIONS · INTERNATIONAL STUDENTS', 'Dedicated admission cell for international, NRI, and foreign scholar applications across 30+ global countries.', 'images/lovable/rkdf-students-quad.jpg', 'Global Scholar Admission & Student Exchange Cell', 'RKDF University welcomes international students from Asia, Africa, Europe, and the Middle East.\n\nOur International Students Cell provides visa assistance, residential hostel booking, english language support, and credit equivalence services.', 'rkdf, university, bhopal, for international admissions', 'Dedicated international student cell facilitating foreign admissions, visa processing, FRRO support, and cultural integration.', '1', '5', '2026-08-14 12:03:42'),
('68', 'academic-departments', 'Faculties, Schools & Academic Departments Directory', 'admissions', 'ACADEMICS · SCHOOLS & DEPARTMENTS', 'Comprehensive directory of university faculties, departments, degree programs, and academic laboratories.', 'images/lovable/rkdf-students-quad.jpg', 'RKDF University Academic Faculties', 'RKDF University comprises 15+ constituent faculties including Engineering & Technology, Pharmacy, Management, Agriculture, Ayurvedic Medicine (BAMS), Homeopathy (BHMS), Nursing, Law, and Architecture.\n\nExplore our degree programs and department profiles below.', 'rkdf, university, bhopal, faculties and departments', 'Complete directory of constituent faculties, research departments, and professional colleges under RKDF University Bhopal.', '1', '6', '2026-08-14 12:03:42'),
('69', 'bank-details', 'University Official Bank Account & Payment Details', 'admissions', 'ADMISSIONS · NEFT / RTGS BANK DETAILS', 'Official bank account details for fee submission via NEFT, RTGS, IMPS, and Demand Draft.', 'images/lovable/rkdf-students-quad.jpg', 'Official Bank Account Transfer Information', 'Students and parents paying tuition fees via Online Net Banking, NEFT, RTGS, or Demand Draft must remit fees strictly to the official university bank account below.\n\n**Account Name**: RKDF University Bhopal\n**Bank**: Punjab National Bank (PNB)\n**Branch**: Airport Bypass Road, Bhopal\n**Account No**: 6401002100001088\n**IFSC Code**: PUNB0640100', 'rkdf, university, bhopal, university bank account details', 'Official bank accounts for direct NEFT/RTGS tuition fee transfer, DD favoring details, and IFSC codes.', '1', '7', '2026-08-14 12:03:42'),
('71', 'campus-facility', 'Campus Infrastructure & Student Facilities', 'admissions', 'CAMPUS LIFE · INFRASTRUCTURE & FACILITIES', 'World-class campus infrastructure featuring digital smart classrooms, central library, sports complex, hostels, and Wi-Fi campus.', 'images/lovable/rkdf-students-quad.jpg', 'State-of-the-Art Campus Infrastructure', 'Spread over a lush green 55+ acre university campus, RKDF University provides modern learning facilities including high-tech engineering & pharmacy research labs, central library with DELNET, separate AC/Non-AC hostels for boys and girls, 24x7 medical clinic, fleet of campus buses, and a multi-sport arena.', 'rkdf, university, bhopal, campus facility', 'World-class campus facilities including AC hostels, central library, sports complex, cafeteria, Wi-Fi campus, and fleet of buses.', '1', '9', '2026-08-14 12:03:42'),
('73', 'pay-paytm', 'Pay Tuition & Exam Fees Online via Paytm Gateway', 'admissions', 'STUDENT SERVICES · ONLINE FEE PAYMENT', 'Instant online payment of tuition fees, hostel fees, and exam fees using Paytm, UPI, Credit Card, Debit Card, or Net Banking.', 'images/lovable/rkdf-students-quad.jpg', 'Instant Digital Fee Payment Gateway', 'RKDF University provides a secure online fee payment portal powered by Paytm.\n\nStudents can pay fees anywhere using UPI apps (GPay, PhonePe, Paytm), Credit Cards, Debit Cards, or Net Banking and instantly download official payment receipts.', 'rkdf, university, bhopal, pay fees through paytm', 'Instant online tuition fee payment portal via Paytm UPI, NetBanking, Credit/Debit cards with digital receipt generation.', '1', '11', '2026-08-14 12:03:42'),
('74', 'inhouse-scheme', 'RKDF Group Staff & Alumni In-House Concession Scheme', 'admissions', 'SCHOLARSHIPS · IN-HOUSE SCHEME', 'Special tuition fee concession policy for wards of RKDF Group employees, alumni, and continuing scholars.', 'images/lovable/rkdf-students-quad.jpg', 'RKDF In-House Fee Concession Policy', 'To support faculty staff families and university alumni, RKDF University provides special tuition fee concessions under the In-House Concession Scheme.\n\nReview the official eligibility policy below.', 'rkdf, university, bhopal, inhouse scheme policy', 'Special fee concession policy for RKDF Group alumni and internal students progressing from UG to PG programs.', '1', '12', '2026-08-14 12:03:42'),
('75', 'meritorious-scheme', 'RKDF Meritorious Student Scholarship Policy', 'admissions', 'SCHOLARSHIPS · MERIT SCHOLARSHIPS', 'Merit-based tuition fee scholarships for top rankers in qualifying board examinations and entrance tests.', 'images/lovable/rkdf-students-quad.jpg', 'Meritorious Student Scholarship Scheme', 'RKDF University awards merit scholarships to high-achieving students scoring above 80% marks in 10+2 board examinations, JEE Main, or CUET UG.\n\nReview the scholarship slab percentages and renewal criteria below.', 'rkdf, university, bhopal, meritorious scheme policy', 'Scholarship policy rewarding academic toppers in 10+2 board exams and national competitive entrance tests.', '1', '13', '2026-08-14 12:03:42'),
