('157', 'convocation-2023-24', 'Convocation Medals 2023-24', 'academic', 'ACADEMIC · CONVOCATION', 'Official list of Gold & Silver Medalists for Academic Session 2023-24.', 'images/lovable/rkdf-students-quad.jpg', 'Convocation Honor Roll 2023-24', 'Recognizing academic toppers across undergraduate and postgraduate programs.', 'rkdf, university, bhopal, convocation medals 2023-24', 'Official list of Gold & Silver Medalists for Academic Session 2023-24.', '1', '30', '2026-08-06 15:15:06'),
