('850', 'terms&condition', 'Statutory Terms of Use Clauses', 'General Information & Website Content Usage', 'Clause 01', '1', 'The content of the pages of this website is for your general information and academic use only. It is subject to change without prior notice.', 'images/lovable/rkdf-why-bg.jpg', '#', 'TERM 01', '1', '1', '2026-08-14 12:33:34', '2026-08-14 12:33:34'),
('851', 'terms&condition', 'Statutory Terms of Use Clauses', 'Warranty & Disclaimer of Accuracy', 'Clause 02', '2', 'Neither we nor any third parties provide any warranty or guarantee as to the accuracy, timeliness, performance, completeness, or suitability of the information and materials found or offered on this website for any particular purpose.', 'images/lovable/rkdf-why-bg.jpg', '#', 'TERM 02', '2', '1', '2026-08-14 12:33:34', '2026-08-14 12:33:34'),
('852', 'terms&condition', 'Statutory Terms of Use Clauses', 'User Risk & Service Requirements', 'Clause 03', '3', 'Your use of any information or materials on this website is entirely at your own risk. It shall be your own responsibility to ensure that any products, services, or information available through this website meet your specific requirements.', 'images/lovable/rkdf-why-bg.jpg', '#', 'TERM 03', '3', '1', '2026-08-14 12:33:34', '2026-08-14 12:33:34'),
('853', 'terms&condition', 'Statutory Terms of Use Clauses', 'Reservation of Right to Refuse Service', 'Clause 04', '4', 'RKDF University reserves the right to refuse service, reject applications, or restrict portal access to anyone at any time in accordance with university regulations.', 'images/lovable/rkdf-why-bg.jpg', '#', 'TERM 04', '4', '1', '2026-08-14 12:33:34', '2026-08-14 12:33:34'),
('854', 'terms&condition', 'Statutory Terms of Use Clauses', 'Intellectual Property & Copyright Protection', 'Clause 05', '5', 'This website contains material which is owned by or licensed to us, including design, layout, look, graphics, and trademarks. Reproduction is prohibited except in accordance with copyright law.', 'images/lovable/rkdf-why-bg.jpg', '#', 'TERM 05', '5', '1', '2026-08-14 12:33:34', '2026-08-14 12:33:34'),
('855', 'terms&condition', 'Statutory Terms of Use Clauses', 'Trademark Acknowledgment', 'Clause 06', '6', 'All trademarks reproduced in this website which are not the property of, or licensed to, the operator are acknowledged on the website.', 'images/lovable/rkdf-why-bg.jpg', '#', 'TERM 06', '6', '1', '2026-08-14 12:33:34', '2026-08-14 12:33:34'),
('856', 'terms&condition', 'Statutory Terms of Use Clauses', 'Unauthorized Use & Penalties', 'Clause 07', '7', 'Unauthorized use, hacking, or tampering with this website or database may give rise to a claim for damages and/or be a criminal offense under Indian IT Law.', 'images/lovable/rkdf-why-bg.jpg', '#', 'TERM 07', '7', '1', '2026-08-14 12:33:34', '2026-08-14 12:33:34'),
('857', 'terms&condition', 'Statutory Terms of Use Clauses', 'External Links & Hyperlinks Disclaimer', 'Clause 08', '8', 'This website may include links to external portals (such as NTA, UGC, DELNET). These links are provided for convenience and do not signify university endorsement.', 'images/lovable/rkdf-why-bg.jpg', '#', 'TERM 08', '8', '1', '2026-08-14 12:33:34', '2026-08-14 12:33:34'),
('858', 'terms&condition', 'Statutory Terms of Use Clauses', 'Linking Policy', 'Clause 09', '9', 'You may not create a hyperlink to this website from another website or document without prior written consent from RKDF University administration.', 'images/lovable/rkdf-why-bg.jpg', '#', 'TERM 09', '9', '1', '2026-08-14 12:33:34', '2026-08-14 12:33:34'),
('859', 'terms&condition', 'Statutory Terms of Use Clauses', 'Governing Law & Legal Jurisdiction', 'Clause 10', '10', 'Your use of this website and any legal dispute arising out of such use is subject to the laws of India and falls exclusively under the jurisdiction of the Courts of Bhopal, Madhya Pradesh.', 'images/lovable/rkdf-why-bg.jpg', '#', 'TERM 10', '10', '1', '2026-08-14 12:33:34', '2026-08-14 12:33:34'),
('860', 'privacy', 'Statutory Privacy Standards', 'Personal Data Security & Employee NDA Agreements', 'Confidentiality Protocol', '1', 'The University protects personal information collected from students, graduates, staff, and business partners. All full-time and part-time employees and student interns sign an Employee Non-Disclosure and Confidentiality Agreement.', 'images/lovable/rkdf-why-bg.jpg', '#', 'DATA SECURITY', '1', '1', '2026-08-14 12:34:52', '2026-08-14 12:34:52'),
('861', 'privacy', 'Statutory Privacy Standards', 'Authorized Access & Academic Need-to-Know Limits', 'Access Control', '2', 'Access to personal records is restricted to: (1) Individuals accessing their own records, (2) Employees with legitimate academic need, (3) Authorized third parties, and (4) Legal or statutory bodies compelled by law.', 'images/lovable/rkdf-why-bg.jpg', '#', 'ACCESS CONTROL', '2', '1', '2026-08-14 12:34:52', '2026-08-14 12:34:52'),
('862', 'privacy', 'Statutory Privacy Standards', 'Non-Commercial Data Use & Marketing Disclosure Protection', 'No Commercial Sale', '3', 'RKDF University does not sell, rent, or trade student personal information to third parties for marketing purposes.', 'images/lovable/rkdf-why-bg.jpg', '#', 'NO MARKETING SALE', '3', '1', '2026-08-14 12:34:52', '2026-08-14 12:34:52'),
('863', 'privacy', 'Statutory Privacy Standards', 'Degree Verification & Public Academic Standing Inquiries', 'Verification Inquiries', '4', 'The University may confirm public inquiries as to whether an individual holds a degree or diploma in good standing from RKDF University through official portals.', 'images/lovable/rkdf-why-bg.jpg', '#', 'VERIFICATION STANDING', '4', '1', '2026-08-14 12:34:52', '2026-08-14 12:34:52'),
('864', 'privacy', 'Statutory Privacy Standards', 'Professional Bodies & Association Membership Benefits', 'Professional Associations', '5', 'Limited name and address information may be shared with recognized professional industry organizations (e.g. AICTE, PCI, BCI, DELNET) solely for membership eligibility and professional benefits.', 'images/lovable/rkdf-why-bg.jpg', '#', 'PROFESSIONAL BODIES', '5', '1', '2026-08-14 12:34:52', '2026-08-14 12:34:52'),
