('1', 'scholarship', 'schemes', 'Mukhyamantri Medhavi Vidyarthi Yojana (MMVY)', 'State Govt Scheme', '01', 'For MP domicile students scoring 75%+ in MP Board or 85%+ in CBSE/ICSE in Class 12th. JEE Mains rank under 50,000 or NEET/CLAT qualified.', '', '', 'State Sponsored', '1', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('2', 'scholarship', 'schemes', 'Post Matric Scholarship for OBC Students', 'State Govt Scheme', '02', 'For OBC category students at post-secondary level. Family annual income less than 75,000 INR (100% scholarship) or up to 1,00,000 INR (50% scholarship).', '', '', 'OBC Quota', '2', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('3', 'scholarship', 'schemes', 'Post Matric Scholarship for SC Students', 'State Govt Scheme', '03', 'Financial assistance for Scheduled Caste students pursuing higher education at RKDF University.', '', '', 'SC Category', '3', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('4', 'scholarship', 'schemes', 'Post Matric Scholarship for ST Students', 'State Govt Scheme', '04', 'Full/partial fee waiver for ST students. Family income under 2.5 Lakhs (100%) or between 2.5L to 6L (50%).', '', '', 'ST Category', '4', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('5', 'scholarship', 'schemes', 'Central Minority Scholarship Scheme', 'National Govt Scheme', '05', 'Merit-cum-means financial aid provided by Government of India for students belonging to minority communities.', '', '', 'National Tier', '5', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('6', 'scholarship', 'portals', 'Madhya Pradesh State Scholarship Portal', 'Official Portal', '', 'MP State e-Scholarship 2.0 portal for SC/ST/OBC/MMVY applications.', '', 'http://scholarshipportal.mp.nic.in/Index.aspx', 'MP Portal', '1', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('7', 'scholarship', 'portals', 'Uttar Pradesh Scholarship Portal', 'Official Portal', '', 'UP State online scholarship application portal for UP domicile students.', '', 'https://scholarship.up.gov.in/', 'UP Portal', '2', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('8', 'scholarship', 'portals', 'Bihar Post Matric Scholarship Portal', 'Official Portal', '', 'Bihar PMS Online portal for Bihar state candidates studying at RKDF.', '', 'https://pmsonline.bih.nic.in/', 'Bihar Portal', '3', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('9', 'scholarship', 'portals', 'Uttarakhand SC/ST/OBC Scholarship Scheme', 'Official Portal', '', 'Government of Uttarakhand online scholarship scheme.', '', 'https://govtschemes.in/', 'UK Portal', '4', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('10', 'scholarship', 'portals', 'Jharkhand e-Kalyan Portal', 'Official Portal', '', 'Jharkhand e-Kalyan portal for welfare and post-matric scholarship.', '', 'https://ekalyan.cgg.gov.in/', 'Jharkhand Portal', '5', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('11', 'scholarship', 'portals', 'National Scholarship Portal (Minority)', 'Central Portal', '', 'Government of India central NSP portal for minority scholarships.', '', 'https://scholarships.gov.in/', 'NSP Central', '6', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('12', 'scholarship', 'docs', 'Caste Certificate (Attested Photocopy)', 'Required Document', '', 'Mandatory for SC/ST/OBC category applicants.', '', '', 'Category Proof', '1', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('13', 'scholarship', 'docs', 'MP Domicile / Residence Proof', 'Required Document', '', 'Required for MP state government schemes.', '', '', 'Domicile', '2', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('14', 'scholarship', 'docs', 'Parents Income Certificate (Latest)', 'Required Document', '', 'Issued by competent authority for fee waiver eligibility.', '', '', 'Income Proof', '3', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
('15', 'scholarship', 'docs', 'Previous Year Marksheets & Transfer Certificate', 'Required Document', '', 'Attested copies of qualifying examination marksheets and TC.', '', '', 'Academic', '4', '1', '2026-08-04 12:55:07', '2026-08-04 12:55:07'),
